-- Reference migration for the saved audit questions (`TomSqlAuditQuestionStore`).
--
-- Creates `tom_audit_question`: an auditor's questions of the audit trail,
-- with their schedules and recipients. This file is the canonical DDL and is
-- kept in sync with `auditQuestionTable()` in
-- `lib/src/tomserver/audit_reports/audit_question_sql.dart`;
-- `test/framework_schema_test.dart` replays this chain and compares the schema
-- it builds against the descriptor, so the two cannot drift apart.
--
-- Apply this file when the application's database user is not permitted to run
-- DDL, and construct the store with `createSchema: false`. A store over a
-- renamed table ships no migration of its own: call
-- `auditQuestionTableDdl(name)` with the name you passed the constructor and
-- apply what it returns.
--
-- Notes on the shape:
--
--  * `id` is the primary key, a UUID the service gives a new question.
--  * `definition` is the question's filter, recipients and format as JSON — the
--    parts no statement filters on.
--  * `(owner, name)` is indexed for listing an auditor's questions by name;
--    `next_delivery_at` for the delivery pass, which reads the questions due.
--  * `schedule` is a five-field cron expression in UTC, NULL for a question
--    never delivered on a schedule.
--  * instants are DATETIME(6) and are always written in UTC.
CREATE TABLE IF NOT EXISTS tom_audit_question (
  id VARCHAR(64) NOT NULL,
  owner VARCHAR(191) NOT NULL,
  name VARCHAR(255) NOT NULL,
  definition TEXT NOT NULL,
  schedule VARCHAR(255) NULL,
  next_delivery_at TIMESTAMP(6) NULL,
  last_delivered_at TIMESTAMP(6) NULL,
  updated_at TIMESTAMP(6) NOT NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_tom_audit_question_owner ON tom_audit_question (owner, name);

CREATE INDEX IF NOT EXISTS ix_tom_audit_question_due ON tom_audit_question (next_delivery_at);
